function validate([stones]) {
  if (!Array.isArray(stones) || stones.length < 2 || stones.length > 100000) return 'stones needs 2 to 100000 values.';
  if (stones.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each stone is an integer from -10000 to 10000.';
  return null;
}

