function stoneGameVIII(stones) {
  // Plays the real game: try every x on the actual row and recurse on the new row.
  const play = (row) => {
    if (row.length === 1) return 0;
    let result = -Infinity;
    let taken = 0;
    for (let x = 1; x <= row.length; x++) {
      taken += row[x - 1];
      if (x < 2) continue;
      const next = [taken, ...row.slice(x)];
      result = Math.max(result, taken - play(next));
    }
    return result;
  };
  return play(stones.slice());
}

