function generate(rand, size) {
  if (size === 'small') {
    const n = 2 + Math.floor(rand() * 7);
    const span = [1, 5, 20, 10000][Math.floor(rand() * 4)];
    return [Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span)];
  }
  const n = 2000;
  const bias = Math.floor(rand() * 3) - 1;
  return [Array.from({ length: n }, () => Math.floor(rand() * 20001) - 10000 + bias * Math.floor(rand() * 3000))
    .map(v => Math.max(-10000, Math.min(10000, v)))];
}
